head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P1.xml";
window.onunload = function() {
    opener.fn_getBeforeRadioBtn("ALL");
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_Top);

    // 조회
    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_Year.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(panel_Top);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.year" + "&outputMessageId=FIS_YEAR_LIST" + "&param01=Y";
    dts_Year.DataID = encodeURI(url);
    dts_Year.Reset();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = async function() {
    var nRow = dts_Year.getRowPosition();
    if (nRow < 1) {
        return;
    }
    var sItemCd = dts_Year.getCellData(nRow, "YYYY");
    var sItemNM = dts_Year.getCellData(nRow, "YYYY");
    var sItemTyp = "0"; // 0:년도, 1:계정, 3:회사
    var sAxisTyp = "1"; // AXIS_TYP  1:기준, 2: 가로, 3:세로
    var sColYear = "0000"; // COL_YEAR

    if (sItemCd != "") {
        var arrPar = new Array();
        arrPar[0] = {
            ITEM_CD: sItemCd,
            ITEM_NM: sItemNM,
            ITEM_TYP: sItemTyp,
            AXIS_TYP: sAxisTyp,
            COL_YEAR: sColYear
        };
        $c.frame.path("../").fn_SetAxisInfo(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.dts_Year_OnLoadError = function() {
    $c.stf.alert_error(dts_Year);
};
scwin.dts_Year_OnLoadCompleted = function(rowcount) {
    if (dts_Year.errorMsg) {
        $c.win.alert(dts_Year.errorMsg);
    }
    $c.cm.CloseWin(rowcount, panel_Top);
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_Close_onclick = async function() {
    // 닫기버튼 클릭
    // opener.fn_getBeforeRadioBtn("ALL");
    await $c.frame.CloseFrame();
};
scwin.img_Confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.fn_SetParam();
};
scwin.trv_Year_OnDblClick = function() {
    scwin.fn_SetParam();
};
